export interface DiseaseRecord { id:string; slug:string; title:string; specialty:string; category:string; classification:string[]; relatedSpecialties?:string[]; emergencyClassification?:string[]; oncologyClassification?:string[]; familyMeta?:{family:string; parentDisease?:string; relationToParent?:string; population?:string; canonicalDisease?:string}|null; }
export interface AtlasViewSnapshot { modelReferences?:Array<{organId:string;url:string;renderingAsset?:string;meshCount:number;sources:Array<{url:string;md5?:string;sha256?:string;file?:string;ontologyId?:string;groups?:string[]}>}>;selectedDetailStructure?:{id:string;label:string;kind:"schematic";references:string[]}|null;selectedStructure?:StructureIdentity|null;detailModel?:{id:string;kind:"schematic";revision:number;references:string[];notice:string}|null; schemaVersion:1; organId:string; context?:"oral-region"|"female-reproductive"|"upper-digestive"|"urinary-tract"|"cardiopulmonary"|"hepatopancreatic"|null; modelRevision:string; selectedPartId:string|null; presentation?:{explodeLayout?:"anatomical-assemblies-v1";quality?:"light"|"original";side:"L"|"R"|null;explode:number}; scenarioStates:Record<string,{id:string|null;side?:"L"|"R"|null;partId?:string|null;intensity:number}>; inspection:{organ?:string;mode:string;side:string;route:string;slice:boolean;cut:number}; camera:{position:number[];target:number[]}; motion:{playing:boolean;speed:number;timeSeconds?:number}; }
