// Disease id/slug are retained from medicine-web, not regenerated. A production migration should
// map these source keys to immutable DB primary keys and retain aliases when documents are renamed.

export interface StructureIdentity { organId:string; partId:string; source:string; ontologyId:string|null; ontologyLabel:string|null; mappingStatus:"source-mapped"|"unmapped";mappingEvidence?:"source-glb-extras"|"source-catalog"|null; review:{status:"needs-review"|"not-expert-reviewed";issues:Array<{code:string;message:string;evidence:string}>}; }
